//! Compiled-in PostgreSQL 18.6 builtin catalog rows (TYPE-02, TYPE-12).
//!
//! The row tables in `types.rs`, `procs.rs`, `operators.rs`, `casts.rs` and `aggregates.rs` are
//! GENERATED by `python3 crates/pgarbor-types/gen/gen_tables.py` from `contracts/reference/pg18/*.csv`
//! (plus `crates/pgarbor-types/gen/pg_proc_args.csv`). Never edit them by hand.
//!
//! Every table is sorted ascending by OID so lookups are binary searches. The tables contain EVERY
//! builtin row (including types/procs PGArbor does not implement): overload resolution must see the
//! same candidate set as PostgreSQL, and `pgarbor-catalog` serves them as the virtual
//! `pg_type`/`pg_proc`/`pg_operator`/`pg_cast`/`pg_aggregate` relations.
//!
//! CONTRACT: the struct shapes and the enums below are frozen (v1).
use pgarbor_common::Oid;

pub mod aggregates;
pub mod casts;
pub mod operators;
pub mod procs;
pub mod types;

pub use aggregates::AGGREGATES;
pub use casts::CASTS;
pub use operators::OPERATORS;
pub use procs::PROCS;
pub use types::TYPES;

/// One `pg_type` row. Field names follow `pg_type` columns without the `typ` prefix.
// CONTRACT
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct BuiltinType {
    pub oid: Oid,
    pub name: &'static str,
    /// `typnamespace` (11 = pg_catalog, 13293 = information_schema).
    pub namespace: Oid,
    /// `typlen`: fixed byte length, -1 = varlena, -2 = cstring.
    pub len: i16,
    pub byval: bool,
    /// `typtype`: b'b' base, b'c' composite, b'd' domain, b'e' enum, b'p' pseudo, b'r' range, b'm' multirange.
    pub typtype: u8,
    /// `typcategory`: b'A' array, b'B' boolean, b'C' composite, b'D' date/time, b'E' enum, b'G' geometric,
    /// b'I' network, b'N' numeric, b'P' pseudo, b'R' range, b'S' string, b'T' timespan, b'U' user,
    /// b'V' bit string, b'X' unknown, b'Z' internal.
    pub category: u8,
    /// `typispreferred` (preferred type within its category, used by overload resolution).
    pub preferred: bool,
    /// `typdelim`: array element delimiter in text form (b',' for all but `box` which uses b';').
    pub delim: u8,
    /// `typrelid`: pg_class OID for composite types, else 0.
    pub relid: Oid,
    /// `typelem`: element type for array types (and for fixed-length "vector" types such as `name`), else 0.
    pub elem: Oid,
    /// `typarray`: OID of the array type whose element is this type, or 0.
    pub array: Oid,
    /// `typinput` / `typoutput` / `typreceive` / `typsend` regproc names (e.g. "int4in").
    pub input: &'static str,
    pub output: &'static str,
    pub receive: &'static str,
    pub send: &'static str,
    /// `typalign`: b'c' char, b's' short, b'i' int, b'd' double.
    pub align: u8,
    /// `typstorage`: b'p' plain, b'e' external, b'm' main, b'x' extended.
    pub storage: u8,
    /// `typbasetype` (domains only).
    pub basetype: Oid,
    /// `typtypmod` (domains only; -1 otherwise).
    pub typmod: i32,
    /// `typndims` (domains over arrays only).
    pub ndims: i32,
    /// `typcollation`: 100 (default) for collatable types, 950 (`C`) for `name`, else 0.
    pub collation: Oid,
}

/// `prokind`.
// CONTRACT
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum ProcKind {
    Function,
    Aggregate,
    Window,
    Procedure,
}

impl ProcKind {
    /// The single-character `prokind` value (`f`, `a`, `w`, `p`).
    pub fn as_char(self) -> char {
        match self {
            ProcKind::Function => 'f',
            ProcKind::Aggregate => 'a',
            ProcKind::Window => 'w',
            ProcKind::Procedure => 'p',
        }
    }
}

/// `provolatile`.
// CONTRACT
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Volatility {
    Immutable,
    Stable,
    Volatile,
}

impl Volatility {
    /// The single-character `provolatile` value (`i`, `s`, `v`).
    pub fn as_char(self) -> char {
        match self {
            Volatility::Immutable => 'i',
            Volatility::Stable => 's',
            Volatility::Volatile => 'v',
        }
    }
}

/// Which PGArbor source module implements a builtin proc. Assigned by the generator's `classify()`;
/// the assignment is frozen (it defines lease ownership of each PostgreSQL function).
///
/// `func::implementation()` routes a proc to `<module>::lookup(proc)`; see `crate::func`.
// CONTRACT
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum ImplModule {
    /// crate::scalar::bool
    Bool,
    /// crate::scalar::int_ops
    IntOps,
    /// crate::scalar::float_ops
    FloatOps,
    /// crate::numeric::funcs
    Numeric,
    /// crate::scalar::oid_types
    OidTypes,
    /// crate::text::funcs
    Text,
    /// crate::text::format
    TextFormat,
    /// crate::text::like
    Like,
    /// crate::text::regex
    Regex,
    /// crate::bytea
    Bytea,
    /// crate::crypto
    Crypto,
    /// crate::uuid
    Uuid,
    /// crate::datetime::date
    Date,
    /// crate::datetime::time
    Time,
    /// crate::datetime::timestamp
    Timestamp,
    /// crate::datetime::interval
    Interval,
    /// crate::datetime::funcs
    DatetimeFuncs,
    /// crate::formatting
    Formatting,
    /// crate::json::ops
    JsonOps,
    /// crate::json::build
    JsonBuild,
    /// crate::json::srf
    JsonSrf,
    /// crate::array::funcs
    ArrayFuncs,
    /// crate::record
    Record,
    /// crate::enum_type
    Enum,
    /// crate::system_funcs
    System,
    /// crate::func::series
    Series,
    /// crate::typmod (length-coercion functions such as `varchar(varchar,int4,bool)`)
    Typmod,
    /// crate::agg::basic (prokind 'a')
    AggBasic,
    /// crate::agg::collect (prokind 'a')
    AggCollect,
    /// crate::agg::stats (prokind 'a')
    AggStats,
    /// crate::agg::ordered_set (prokind 'a', ordered-set / hypothetical-set aggregates)
    AggOrderedSet,
    /// Window functions (prokind 'w'): evaluated by pgarbor-exec's window operator.
    Window,
    /// Needs catalog / session / engine state: implemented by a downstream crate through
    /// `SessionContext::call_external` (e.g. `nextval`, `pg_get_expr`, `has_table_privilege`).
    External,
    /// Not targeted (geometry, network, ranges, tsearch, xml, replication, stats, I/O procs ...):
    /// crate::extra_types reports the 0A000 error.
    Unsupported,
}

/// `oprkind`.
// CONTRACT
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum OprKind {
    /// b'b': binary (infix) operator.
    Infix,
    /// b'l': prefix (left-unary) operator, `oprleft = 0`.
    Prefix,
}

/// One `pg_proc` row (+ argument metadata from pg_proc_args.csv).
// CONTRACT
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct BuiltinProc {
    pub oid: Oid,
    pub name: &'static str,
    pub namespace: Oid,
    pub kind: ProcKind,
    /// `prorettype`.
    pub ret: Oid,
    /// `proretset` (set-returning function).
    pub retset: bool,
    pub volatility: Volatility,
    /// `proisstrict`: NULL input => NULL result, function not called (enforced by `crate::func`).
    pub strict: bool,
    pub nargs: u16,
    /// `pronargdefaults`: the last `ndefaults` input args have defaults (`arg_defaults`).
    pub ndefaults: u16,
    /// `proargtypes`: input argument types only.
    pub arg_types: &'static [Oid],
    /// `provariadic`: element type of the VARIADIC parameter (`2276` = "any"), or 0.
    pub variadic: Oid,
    /// C symbol for internal (lang 12) / C (lang 13) functions; EMPTY for SQL-language (lang 14)
    /// builtins, which PGArbor implements natively and matches by `oid`.
    pub prosrc: &'static str,
    /// `prolang`: 12 internal, 13 C, 14 SQL.
    pub lang: Oid,
    /// `proallargtypes` (empty when all args are IN): includes OUT/TABLE columns.
    pub all_arg_types: &'static [Oid],
    /// `proargmodes`: b'i' in, b'o' out, b'b' inout, b'v' variadic, b't' table; empty = all IN.
    pub arg_modes: &'static [u8],
    /// `proargnames` (parallel to `all_arg_types` when present, else to `arg_types`); may be empty.
    pub arg_names: &'static [&'static str],
    /// `pg_get_expr(proargdefaults)`: comma-separated SQL expressions for the trailing defaults, or "".
    pub arg_defaults: &'static str,
    /// Implementing module (see `ImplModule`).
    pub module: ImplModule,
}

impl BuiltinProc {
    /// Output column (name, type) pairs for functions with OUT/TABLE args (e.g. `jsonb_each` →
    /// `[("key", 25), ("value", 3802)]`). Empty when the function has no OUT args.
    pub fn out_columns(&self) -> Vec<(&'static str, Oid)> {
        let mut out = Vec::new();
        for (i, m) in self.arg_modes.iter().enumerate() {
            if *m == b'o' || *m == b'b' || *m == b't' {
                let name = self.arg_names.get(i).copied().unwrap_or("");
                if let Some(t) = self.all_arg_types.get(i) {
                    out.push((name, *t));
                }
            }
        }
        out
    }
}

/// One `pg_operator` row.
// CONTRACT
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct BuiltinOperator {
    pub oid: Oid,
    pub name: &'static str,
    pub kind: OprKind,
    /// 0 for prefix operators.
    pub left: Oid,
    pub right: Oid,
    pub result: Oid,
    /// `oprcom` (0 if none).
    pub commutator: Oid,
    /// `oprnegate` (0 if none).
    pub negator: Oid,
    /// `oprcode` regproc name.
    pub proc_name: &'static str,
    /// `oprcode` as OID: the operator is evaluated by calling this proc.
    pub proc: Oid,
    pub can_merge: bool,
    pub can_hash: bool,
}

/// `castcontext`, ordered so that `Implicit < Assignment < Explicit` (a cast usable in a weaker
/// context is usable in every stronger one).
// CONTRACT
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum CastContext {
    Implicit,
    Assignment,
    Explicit,
}

/// `castmethod`.
// CONTRACT
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum CastMethod {
    /// b'f': call `func`.
    Function,
    /// b'b': binary coercible, no conversion (relabel).
    Binary,
    /// b'i': via output function of source + input function of target.
    InOut,
}

/// One `pg_cast` row.
// CONTRACT
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct BuiltinCast {
    pub oid: Oid,
    pub source: Oid,
    pub target: Oid,
    /// Cast function proc OID (0 for Binary / InOut).
    pub func: Oid,
    pub context: CastContext,
    pub method: CastMethod,
}

/// `aggkind`.
// CONTRACT
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum AggKind {
    Normal,
    OrderedSet,
    Hypothetical,
}

/// One `pg_aggregate` row. Argument types come from the proc row with the same OID.
// CONTRACT
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct BuiltinAggregate {
    /// `aggfnoid` (= the pg_proc OID of the aggregate).
    pub oid: Oid,
    /// Unqualified aggregate name (e.g. "sum").
    pub name: &'static str,
    pub kind: AggKind,
    pub transfn: &'static str,
    /// "-" when none.
    pub finalfn: &'static str,
    pub transtype: Oid,
    pub initval: Option<&'static str>,
    pub module: ImplModule,
}

/// Binary search a builtin type row by OID.
pub fn builtin_type(oid: Oid) -> Option<&'static BuiltinType> {
    TYPES.binary_search_by_key(&oid, |t| t.oid).ok().map(|i| &TYPES[i])
}

/// Binary search a builtin proc row by OID.
pub fn builtin_proc(oid: Oid) -> Option<&'static BuiltinProc> {
    PROCS.binary_search_by_key(&oid, |p| p.oid).ok().map(|i| &PROCS[i])
}

/// Binary search a builtin operator row by OID.
pub fn builtin_operator(oid: Oid) -> Option<&'static BuiltinOperator> {
    OPERATORS.binary_search_by_key(&oid, |o| o.oid).ok().map(|i| &OPERATORS[i])
}

/// Binary search a builtin aggregate row by aggfnoid.
pub fn builtin_aggregate(oid: Oid) -> Option<&'static BuiltinAggregate> {
    AGGREGATES.binary_search_by_key(&oid, |a| a.oid).ok().map(|i| &AGGREGATES[i])
}

/// The `pg_cast` row for exactly (source, target), if any.
pub fn builtin_cast(source: Oid, target: Oid) -> Option<&'static BuiltinCast> {
    CASTS.iter().find(|c| c.source == source && c.target == target)
}

/// All builtin procs with the given name (any namespace), in OID order.
pub fn procs_named(name: &str) -> impl Iterator<Item = &'static BuiltinProc> + '_ {
    PROCS.iter().filter(move |p| p.name == name)
}

/// All builtin operators with the given name, in OID order.
pub fn operators_named(name: &str) -> impl Iterator<Item = &'static BuiltinOperator> + '_ {
    OPERATORS.iter().filter(move |o| o.name == name)
}
